To address the issues with the photo gallery, I will update **`components/About.tsx`**.

**Changes made:**
1.  **Image Display in Modal**: Switched to `object-contain` and `h-full w-full` inside a fixed-height container (`h-[80vh]`). This ensures the entire image is visible regardless of its aspect ratio, without getting cut off.
2.  **Peacock Tail Animation**: Completely reworked the hover animation. The cards now sit in a stack and "fan out" radially (like a hand of cards or peacock tail) when the cursor hovers over the container.
3.  **Descriptions**: Added a `description` field to the photo data with placeholder text. This text is now displayed in the gallery modal below the image.

# Updated files:

## components/About.tsx

- **Animation**: Implemented a "Fan Out" effect using `calc` for rotation and translation based on the card's index.
- **Modal**: Fixed layout to use `h-[80vh]` and `object-contain` so images aren't cropped. Added a description section.
- **Data**: Added dummy descriptions to `PHOTOS`.

```tsx
import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { X, ChevronLeft, ChevronRight } from 'lucide-react';

// --- CONFIGURATION ---
const EXTERNAL_IMAGE_LINKS = [
  // Placeholder 1: Portrait
  "https://drive.google.com/thumbnail?id=14W6GzlPk2BOvkVFJ7P_IcEM5LRtqTWm9&sz=w1000", 
  // Placeholder 2: DJ / Stage
  "https://drive.google.com/thumbnail?id=1cabHo0wpT6tg4L1mrZwkIRXGxma2UbqV&sz=w1000",
  // Placeholder 3: Performance
  "https://drive.google.com/thumbnail?id=1DFr9wme6QCNMuqn6LtU4vt0gQhIWS5Af&sz=w1000"
];

const PHOTOS = EXTERNAL_IMAGE_LINKS.map((url, index) => ({
  id: index,
  src: url,
  alt: ["Profile Portrait", "Live Set @ Purple Haze", "DJ Performance"][index] || "Gallery Image",
  description: [
    "A candid studio portrait capturing the focus required for deep work. Shot on 35mm film in a makeshift studio in Bangalore.",
    "Performing live at Purple Haze. The energy of the crowd fuels the improvisation in the set. A night of pure experimental rhythm.",
    "Mid-set transition. Mixing generative audio with classic hip-hop breaks. This setup involves a custom MIDI controller and Ableton Live."
  ][index] || "Lorem ipsum dolor sit amet, consectetur adipiscing elit. Sed do eiusmod tempor incididunt ut labore et dolore magna aliqua."
}));

const features = [
  { title: "Full Stack", desc: "React, Next.js, FastAPI" },
  { title: "AI / ML", desc: "PyTorch, LLMs, GANs" },
  { title: "Backend", desc: "Postgres, Docker, AWS" },
  { title: "Solutions", desc: "Scalable Architecture" }
];

const About: React.FC = () => {
  const [isGalleryOpen, setIsGalleryOpen] = useState(false);
  const [currentPhotoIndex, setCurrentPhotoIndex] = useState(0);

  const nextPhoto = (e: React.MouseEvent) => {
    e.stopPropagation();
    setCurrentPhotoIndex((prev) => (prev + 1) % PHOTOS.length);
  };

  const prevPhoto = (e: React.MouseEvent) => {
    e.stopPropagation();
    setCurrentPhotoIndex((prev) => (prev - 1 + PHOTOS.length) % PHOTOS.length);
  };

  return (
    <section id="about" className="grid grid-cols-1 md:grid-cols-2">
      {/* Left Col: Interactive Photo Stack */}
      <div className="p-16 md:p-24 border-b md:border-b-0 md:border-r border-fg flex flex-col justify-center items-center bg-bg relative overflow-hidden min-h-[500px]">
        <div className="absolute inset-0 opacity-5" style={{ backgroundImage: 'radial-gradient(circle, currentColor 1px, transparent 1px)', backgroundSize: '20px 20px' }}></div>

        {/* The Stack */}
        <div 
          className="relative w-64 h-80 cursor-pointer group flex items-center justify-center"
          onClick={() => setIsGalleryOpen(true)}
        >
            {PHOTOS.map((photo, index) => {
               // Calculate "Fan" angles
               // Center index is roughly (length - 1) / 2
               // We want them to spread out symmetrically
               const offset = index - (PHOTOS.length - 1) / 2; 
               const rotateAngle = offset * 15; // -15, 0, 15
               const translateX = offset * 40; // -40, 0, 40

               return (
                 <motion.div
                    key={photo.id}
                    className="absolute w-full h-full border-[8px] border-bg shadow-[0_4px_20px_rgba(0,0,0,0.15)] bg-fg overflow-hidden origin-bottom"
                    initial={{ rotate: index * 4 - 4, y: 0, x: 0 }} // Messy stack init
                    whileHover={{
                        rotate: rotateAngle,
                        x: translateX,
                        y: -10, // Lift slightly
                        zIndex: 10, // Ensure hover doesn't clip weirdly (though standard stacking applies)
                        transition: { type: 'spring', stiffness: 200, damping: 15 }
                    }}
                    style={{ 
                        zIndex: index, // Ensure logical stacking (0 back, 2 front)
                    }}
                 >
                    <img 
                        src={photo.src} 
                        alt={photo.alt} 
                        className="w-full h-full object-cover grayscale hover:grayscale-0 transition-all duration-500"
                    />
                 </motion.div>
               )
            })}

            <div className="absolute -bottom-20 left-0 right-0 text-center opacity-0 group-hover:opacity-100 transition-opacity flex justify-center pointer-events-none">
                <span className="font-mono text-xs uppercase bg-fg text-bg px-3 py-1 tracking-widest">View Gallery</span>
            </div>
        </div>
      </div>

      {/* Right Col: Content */}
      <div className="flex flex-col">
        <div className="p-8 md:p-16 border-b border-fg">
          <h2 className="text-4xl font-serif italic mb-8">About Me</h2>
          <p className="font-mono text-sm leading-7 mb-6">
            I approach software engineering with a brutalist philosophy: function dictates form, but form must evoke emotion. My background bridges the gap between traditional CS fundamentals and the bleeding edge of Generative AI.
          </p>
          <p className="font-mono text-sm leading-7">
            Currently focused on building scalable systems that leverage Machine Learning to solve real-world inefficiencies. Beyond the code, I explore the intersection of technology and art through music and visual experiments.
          </p>
        </div>

        <div className="flex-1 grid grid-cols-1 sm:grid-cols-2">
          {features.map((f, i) => (
            <div key={i} className="p-6 border-b sm:border-b-0 border-r border-fg last:border-r-0 sm:nth-last-child(2):border-b-0 odd:border-r hover-invert transition-colors cursor-default group">
              <h3 className="font-serif text-xl mb-2 group-hover:italic">{f.title}</h3>
              <p className="font-mono text-xs opacity-70">{f.desc}</p>
            </div>
          ))}
        </div>
      </div>

      {/* Full Screen Gallery Modal */}
      <AnimatePresence>
        {isGalleryOpen && (
            <motion.div 
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                className="fixed inset-0 z-[60] bg-bg/95 backdrop-blur-md flex items-center justify-center p-4 md:p-8"
                onClick={() => setIsGalleryOpen(false)}
            >
                <button 
                    className="absolute top-4 right-4 md:top-8 md:right-8 p-2 border border-fg hover:bg-fg hover:text-bg transition-colors z-50"
                    onClick={() => setIsGalleryOpen(false)}
                >
                    <X size={24} />
                </button>

                <div 
                    className="relative w-full max-w-6xl h-[85vh] flex flex-col md:grid md:grid-cols-[1fr_300px] border border-fg shadow-[20px_20px_0px_0px_var(--fg)] bg-bg"
                    onClick={(e) => e.stopPropagation()}
                >
                    {/* Image Container */}
                    <div className="relative h-full overflow-hidden bg-black/5 flex items-center justify-center p-4 md:p-8 border-b md:border-b-0 md:border-r border-fg">
                        <AnimatePresence mode="wait">
                            <motion.img
                                key={currentPhotoIndex}
                                src={PHOTOS[currentPhotoIndex].src}
                                alt={PHOTOS[currentPhotoIndex].alt}
                                initial={{ opacity: 0, scale: 0.95 }}
                                animate={{ opacity: 1, scale: 1 }}
                                exit={{ opacity: 0 }}
                                transition={{ duration: 0.3 }}
                                className="max-w-full max-h-full object-contain shadow-lg"
                            />
                        </AnimatePresence>

                        {/* Navigation Arrows (Overlay) */}
                        <div className="absolute inset-0 flex items-center justify-between p-2 md:p-4 pointer-events-none">
                            <button 
                                onClick={prevPhoto}
                                className="pointer-events-auto p-3 bg-bg/80 backdrop-blur border border-fg hover:bg-fg hover:text-bg transition-colors rounded-full md:rounded-none"
                            >
                                <ChevronLeft size={24} />
                            </button>
                            <button 
                                onClick={nextPhoto}
                                className="pointer-events-auto p-3 bg-bg/80 backdrop-blur border border-fg hover:bg-fg hover:text-bg transition-colors rounded-full md:rounded-none"
                            >
                                <ChevronRight size={24} />
                            </button>
                        </div>
                    </div>

                    {/* Sidebar / Description */}
                    <div className="h-full bg-bg flex flex-col">
                        <div className="p-6 border-b border-fg bg-fg text-bg">
                            <span className="font-mono text-xs font-bold uppercase tracking-widest">Image Details</span>
                        </div>
                        <div className="p-6 flex-1 flex flex-col justify-between">
                            <div>
                                <h3 className="font-serif text-2xl italic mb-4 leading-tight">{PHOTOS[currentPhotoIndex].alt}</h3>
                                <div className="w-10 h-1 bg-fg mb-6"></div>
                                <p className="font-mono text-xs md:text-sm leading-relaxed opacity-80">
                                    {PHOTOS[currentPhotoIndex].description}
                                </p>
                            </div>

                            <div className="mt-8 pt-6 border-t border-fg/20 flex justify-between items-end">
                                <span className="font-mono text-[10px] uppercase opacity-50">Gallery Index</span>
                                <span className="font-mono text-xl font-bold">{`0${currentPhotoIndex + 1} / 0${PHOTOS.length}`}</span>
                            </div>
                        </div>
                    </div>
                </div>
            </motion.div>
        )}
      </AnimatePresence>
    </section>
  );
};

export default About;
```

To add the "What I'm Listening To" and "What I'm Watching Now" section for December, I will create a new component `Currents.tsx` and integrate it into the main application layout.

