import React, { useState, useEffect } from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import About from './components/About';
import Projects from './components/Projects';
import Music from './components/Music';
import Experience from './components/Experience';
import Skills from './components/Skills';
import Fun from './components/Fun';
import Contact from './components/Contact';
import ChatWidget from './components/ChatWidget';
import ScrollRobot from './components/ScrollRobot';
import Currents from './components/Currents';
import { Theme } from './types';

const App: React.FC = () => {
  const [currentTheme, setCurrentTheme] = useState<Theme>(Theme.LIGHT);

  useEffect(() => {
    // Check system preference or localStorage
    const storedTheme = localStorage.getItem('theme') as Theme;
    if (Object.values(Theme).includes(storedTheme)) {
      setTheme(storedTheme);
    } else {
      setTheme(Theme.LIGHT);
    }
  }, []);

  const setTheme = (theme: Theme) => {
    setCurrentTheme(theme);
    localStorage.setItem('theme', theme);

    // Reset classes
    document.documentElement.className = 'scroll-smooth';

    // Apply new theme class
    if (theme === Theme.DARK) {
      document.documentElement.classList.add('dark');
    } else if (theme === Theme.RGB) {
      document.documentElement.classList.add('theme-rgb');
    } else if (theme === Theme.VIBGYOR) {
      document.documentElement.classList.add('theme-vibgyor');
    }
    // Light is default (no class)
  };

  return (
    <div className="min-h-screen bg-bg text-fg p-2 md:p-4 transition-colors duration-300">
      <div className="border border-fg relative bg-bg min-h-[95vh]">
        <Navbar currentTheme={currentTheme} setTheme={setTheme} />
        <ScrollRobot />
        <main className="relative">
          <Hero />
          <div className="border-t border-fg">
            <About />
          </div>
          <div className="border-t border-fg">
            <Experience />
          </div>
          <div className="border-t border-fg">
            <Projects />
          </div>
          {/* Skills (Tech Stack) moved here */}
          <div className="border-t border-fg">
            <Skills />
          </div>
          {/* Music (Artist Persona) moved here */}
          <div className="border-t border-fg">
            <Music />
          </div>
          {/* Listening/Watching Section */}
          <div className="border-t border-fg">
            <Currents />
          </div>
          <div className="border-t border-fg">
            <Fun />
          </div>
          <div className="border-t border-fg">
            <Contact />
          </div>
        </main>
      </div>
      <ChatWidget />
    </div>
  );
};

export default App;

To address your feedback, I will replace the "photo stack" animation with a cleaner, more structured **"Digital Scanner / Contact Sheet"** viewer. This fits the brutalist "Feather Computer" aesthetic much better.

**New Design Features:**
1.  **Single Frame Viewer**: Displays one photo at a time in a neat, bordered container.
2.  **Explicit Controls**: Added clearly visible "Previous" and "Next" buttons in a toolbar header.
3.  **Metadata Display**: Shows the filename and a snippet of the description directly in the preview card.
4.  **No Cutoffs**: The preview uses a standard aspect ratio container, but clicking "Enlarge" (or the image) opens the full-screen modal where `object-contain` ensures the whole image is seen.

